entries.description:
(function() {
    var buffer = "";
    buffer += bld + cyn + "CHECK RETOOLS" + nrm + " displays the outstanding item retools handled by the retool-certification NPC. Each entry identifies the affected item and its proposed text changes." + "\n\n";
    buffer += "This is a staff review command that works only at the appropriate NPC. Read the proposed names and descriptions before using the certification instructions shown there. " + bld + cyn + "CHECK" + nrm + " by itself is not a general-purpose item inspection command; use " + bld + cyn + "LOOK" + nrm + " or " + bld + cyn + "EXAMINE" + nrm + " for that." + "\n\n";
    buffer += "Example: " + bld + yel + "check retools" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "RETOOL" + nrm + ", " + bld + cyn + "EXAMINE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "COMPACT" + nrm + " toggles the extra blank line normally printed before your prompt. Turn it on to fit more game output on the screen; type it again to restore the spacing." + "\n\n";
    buffer += "This changes prompt spacing only. Use " + bld + cyn + "BRIEF" + nrm + " to control room descriptions and " + bld + cyn + "TOGGLE" + nrm + " to review your other preferences." + "\n\n";
    buffer += "Example: " + bld + yel + "compact" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "BRIEF" + nrm + ", " + bld + cyn + "TOGGLE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "ENTER" + nrm + " attempts to take you through an entrance in your current room. Specify the entrance keyword when the room provides one. With no argument, it looks for an open exit leading indoors." + "\n\n";
    buffer += "Some entrances have their own requirements, such as an unlocked door, permission from a guard, or progress in a quest. Read the room description for the appropriate keyword. " + bld + cyn + "ENTER ARENA" + nrm + " instead requests entry to the Arena queue or match." + "\n\n";
    buffer += "Example: " + bld + yel + "enter" + nrm + "\n";
    buffer += "Example: " + bld + yel + "enter arena" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "LEAVE" + nrm + ", " + bld + cyn + "OPEN" + nrm + ", " + bld + cyn + "ARENA" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "EQUIPMENT" + nrm + " lists the items you currently have equipped, including your weapon, armor, held item, and light source. Each item appears beside the slot it occupies." + "\n\n";
    buffer += "Items you are carrying but have not equipped appear under " + bld + cyn + "INVENTORY" + nrm + ". Use " + bld + cyn + "WEAR" + nrm + ", " + bld + cyn + "WIELD" + nrm + ", or " + bld + cyn + "HOLD" + nrm + " to equip an item, and " + bld + cyn + "REMOVE" + nrm + " to put equipped items back into your inventory. The usual abbreviation for this command is " + bld + cyn + "EQ" + nrm + "." + "\n\n";
    buffer += "Example: " + bld + yel + "equipment" + nrm + "\n";
    buffer += "Example: " + bld + yel + "eq" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "INVENTORY" + nrm + ", " + bld + cyn + "WEAR" + nrm + ", " + bld + cyn + "WIELD" + nrm + ", " + bld + cyn + "HOLD" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "EXAMINE" + nrm + " takes a closer look at a visible target. Examining a container also shows its accessible contents; a closed container may need to be opened first." + "\n\n";
    buffer += "Some weapons, armor, recipe fragments, and other special items provide additional information when examined. What you can learn depends on the item. Use the target keywords shown by " + bld + cyn + "LOOK" + nrm + " or " + bld + cyn + "INVENTORY" + nrm + "." + "\n\n";
    buffer += "Example: " + bld + yel + "examine chest" + nrm + "\n";
    buffer += "Example: " + bld + yel + "examine sword" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "LOOK" + nrm + ", " + bld + cyn + "INVENTORY" + nrm + ", " + bld + cyn + "OPEN" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "FADE" + nrm + " allows a Myrddraal to travel through the shadows to a room identified by its fading code. Use " + bld + cyn + "SENSE DARKNESS" + nrm + " in a suitable room to learn its code for a future journey." + "\n\n";
    buffer += "You must be unmounted and in a dark room that permits shadow travel. Your Fade skill affects the attempt and how far you can travel. The journey uses shadow strength; protected or inaccessible destinations cannot be reached this way." + "\n\n";
    buffer += "Example: " + bld + yel + "sense darkness" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "SENSE" + nrm + ", " + bld + cyn + "RAGE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "GET" + nrm + " picks up an item from the ground or removes it from a container. Leave out the container name to take something from your room. The item must be visible and available to take, and you must have enough carrying capacity." + "\n\n";
    buffer += "Use " + bld + cyn + "ALL" + nrm + " to take all eligible items, or " + bld + cyn + "ALL.KEYWORD" + nrm + " to take items sharing a keyword. A numbered keyword such as " + bld + cyn + "2.sword" + nrm + " selects a particular matching item. Closed containers must be opened first. " + bld + cyn + "TAKE" + nrm + " is another name for this command." + "\n\n";
    buffer += "Example: " + bld + yel + "get sword" + nrm + "\n";
    buffer += "Example: " + bld + yel + "get coin chest" + nrm + "\n";
    buffer += "Example: " + bld + yel + "get all.bread bag" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "TAKE" + nrm + ", " + bld + cyn + "PUT" + nrm + ", " + bld + cyn + "DROP" + nrm + ", " + bld + cyn + "INVENTORY" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "GIVE" + nrm + " hands an item from your inventory to a visible character in your room. The recipient must be able to carry it. Remove an equipped item before giving it away." + "\n\n";
    buffer += "You can also transfer money by specifying an amount and the word " + bld + cyn + "COINS" + nrm + ". Giving an item or money to an NPC may trigger a purchase, quest, or other interaction, so check that you have selected the intended recipient." + "\n\n";
    buffer += "Example: " + bld + yel + "give bread traveler" + nrm + "\n";
    buffer += "Example: " + bld + yel + "give 10 coins traveler" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "INVENTORY" + nrm + ", " + bld + cyn + "GOLD" + nrm + ", " + bld + cyn + "SHOW" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "GROUP" + nrm + " with no argument displays your group. As the leader, use " + bld + cyn + "GROUP <NAME>" + nrm + " to include a character who is following you and standing in your room. Repeating it for an existing member removes that character from the group." + "\n\n";
    buffer += bld + cyn + "GROUP ALL" + nrm + " adds eligible followers. Following and group membership are separate: " + bld + cyn + "FOLLOW" + nrm + " establishes who leads, while " + bld + cyn + "GROUP" + nrm + " decides who belongs to the party. A character following someone else cannot enroll their own group members." + "\n\n";
    buffer += "Example: " + bld + yel + "group" + nrm + "\n";
    buffer += "Example: " + bld + yel + "group traveler" + nrm + "\n";
    buffer += "Example: " + bld + yel + "group all" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "FOLLOW" + nrm + ", " + bld + cyn + "UNGROUP" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "GUILDS" + nrm + " opens the guild interface. Use its menu to browse guild information and the membership or management options available to your character." + "\n\n";
    buffer += "The interface determines which actions you may take from your membership, rank, and privileges. Follow the menu prompts and use its exit option when finished. Guilds use a separate interface from the clan commands." + "\n\n";
    buffer += "Example: " + bld + yel + "guilds" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "CLAN" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "HAMSTRING" + nrm + " is a Blademaster technique that attempts to wound an opponent and reduce their ability to dodge. You must know the Hamstring skill and use an appropriate sword." + "\n\n";
    buffer += "Specify a visible target in your room, or omit the name to use your current opponent. The attack takes time to prepare and may miss. A target flying out of reach cannot be hamstrung." + "\n\n";
    buffer += "Example: " + bld + yel + "hamstring trolloc" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "WHIRLWIND" + nrm + ", " + bld + cyn + "PRACTICE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "INVERT" + nrm + " prepares your next weave to be inverted. You must know the Invert weave and already be connected to the True Source through " + bld + cyn + "EMBRACE" + nrm + " or " + bld + cyn + "SEIZE" + nrm + "." + "\n\n";
    buffer += "A successful preparation costs spell points. Being shielded prevents the attempt, and loss of concentration can cause it to fail. You cannot prepare another inversion while one is already waiting for your next weave." + "\n\n";
    buffer += "Example: " + bld + yel + "invert" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "SEIZE" + nrm + ", " + bld + cyn + "RELEASE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "KILL" + nrm + " starts ordinary combat against a visible target in your room. The target must be within reach, and the room must permit fighting. For ordinary players this is an attack command, not an instant kill." + "\n\n";
    buffer += bld + cyn + "ATTACK" + nrm + " is an alias for this command. Once combat begins, your character continues making normal attacks. Use " + bld + cyn + "ASSIST" + nrm + " to join an ally against their opponent, or " + bld + cyn + "FLEE" + nrm + " to attempt to escape." + "\n\n";
    buffer += "Example: " + bld + yel + "kill trolloc" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "ATTACK" + nrm + ", " + bld + cyn + "ASSIST" + nrm + ", " + bld + cyn + "FLEE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "KNOCK" + nrm + " announces your presence at a door. Use the door keyword from the room description; a direction can distinguish doors with the same keyword." + "\n\n";
    buffer += "Knocking does not itself unlock or open an ordinary door. Some clan entrances have guards or special responses that decide whether you may enter. Wait for the response and follow any instructions given." + "\n\n";
    buffer += "Example: " + bld + yel + "knock gate" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "OPEN" + nrm + ", " + bld + cyn + "LOCK" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "LEAD" + nrm + " attempts to make an available mount in your room follow you. Your Ride skill affects whether the animal cooperates. Mounts already ridden or following someone else cannot simply be taken over." + "\n\n";
    buffer += "The mount must be suitable for your character. Leading keeps it travelling with you on foot; use " + bld + cyn + "RIDE" + nrm + " to mount it and " + bld + cyn + "DISMOUNT" + nrm + " to get down. Leading a mount does not automatically put another player into a group." + "\n\n";
    buffer += "Example: " + bld + yel + "lead horse" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "RIDE" + nrm + ", " + bld + cyn + "DISMOUNT" + nrm + ", " + bld + cyn + "WHISTLE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "LEVELS" + nrm + " lists how much experience is required to advance from each level to the next. These are individual advancement costs, not cumulative experience totals. Consult the list when planning your next advancement." + "\n\n";
    buffer += "This command displays information only; it does not grant experience or change your level. Use " + bld + cyn + "SCORE" + nrm + " to review your own character and " + bld + cyn + "PRACTICE" + nrm + " to check your training." + "\n\n";
    buffer += "Example: " + bld + yel + "levels" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "SCORE" + nrm + ", " + bld + cyn + "PRACTICE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "LOCK" + nrm + " secures a closed door or container that has a lock. You must have the correct key available. Close an open door or container before trying to lock it." + "\n\n";
    buffer += "Use the door or item keyword, adding a direction for a door when needed to distinguish it. Some locks are controlled by guards or special interactions instead of ordinary keys. Use " + bld + cyn + "UNLOCK" + nrm + " to open a lock you have secured." + "\n\n";
    buffer += "Example: " + bld + yel + "lock chest" + nrm + "\n";
    buffer += "Example: " + bld + yel + "lock gate north" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "CLOSE" + nrm + ", " + bld + cyn + "UNLOCK" + nrm + ", " + bld + cyn + "OPEN" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "MARK" + nrm + " lets a greyman focus on a visible character in the same room. A successful mark replaces the character you were previously focusing on." + "\n\n";
    buffer += "This is a greyman ability rather than an item-marking command. Choose the target by name. Marking someone does not itself strike them or move you to their location." + "\n\n";
    buffer += "Example: " + bld + yel + "mark traveler" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "SHADOWSTEP" + nrm + ", " + bld + cyn + "WHERE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "OPEN" + nrm + " opens a door or container that can be opened. Use its keyword, and add a direction when you need to distinguish between similarly named doors." + "\n\n";
    buffer += "A locked target must first be unlocked or opened through the appropriate special interaction. Opening a container makes its contents accessible; it does not pick them up. Use " + bld + cyn + "GET" + nrm + " to take items from it and " + bld + cyn + "CLOSE" + nrm + " when finished." + "\n\n";
    buffer += "Example: " + bld + yel + "open chest" + nrm + "\n";
    buffer += "Example: " + bld + yel + "open gate north" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "CLOSE" + nrm + ", " + bld + cyn + "UNLOCK" + nrm + ", " + bld + cyn + "GET" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "ORDER" + nrm + " instructs a character under your control to carry out a command. The recipient must be in your room and obey you; an ordinary player following you is not forced to comply." + "\n\n";
    buffer += "Use " + bld + cyn + "FOLLOWERS" + nrm + " to address your eligible followers together. Orders are subject to the follower's normal restrictions and abilities. Giving an order does not guarantee that the requested action can succeed." + "\n\n";
    buffer += "Example: " + bld + yel + "order followers stand" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "FOLLOW" + nrm + ", " + bld + cyn + "GROUP" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "POUR" + nrm + " transfers liquid between suitable containers. The source must contain liquid and the destination must be able to accept it. Existing contents and the destination's capacity may limit what can be transferred." + "\n\n";
    buffer += "Use " + bld + cyn + "OUT" + nrm + " as the destination to empty the source onto the ground. This discards the liquid. Oil can also be used to refill a suitable refillable light. Check both item names before pouring." + "\n\n";
    buffer += "Example: " + bld + yel + "pour flask bottle" + nrm + "\n";
    buffer += "Example: " + bld + yel + "pour flask out" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "INVENTORY" + nrm + ", " + bld + cyn + "LOOK" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "PRACTICE" + nrm + " with no argument lists your skills and remaining training sessions. At a suitable trainer, name the skill or weave you want to improve." + "\n\n";
    buffer += "Trainers teach particular subjects and have their own limits. You need the appropriate practice sessions, and any other requirements the trainer imposes. Away from a trainer, the command displays your skills rather than teaching a new one." + "\n\n";
    buffer += "Example: " + bld + yel + "practice" + nrm + "\n";
    buffer += "Example: " + bld + yel + "practice ride" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "SKILLS" + nrm + ", " + bld + cyn + "SCORE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "PRECISESTRIKE" + nrm + " attempts a carefully aimed weapon attack. You must know the skill and wield a weapon. You may specify a target and body part; while fighting, you can omit the target to use your current opponent." + "\n\n";
    buffer += "The chosen body part must be valid. The target must remain visible and in reach while the attack prepares, and success is not guaranteed. You cannot use this technique to attack someone else while already engaged with an unrelated opponent." + "\n\n";
    buffer += "Example: " + bld + yel + "precisestrike trolloc" + nrm + "\n";
    buffer += "Example: " + bld + yel + "precisestrike" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "KILL" + nrm + ", " + bld + cyn + "PRACTICE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "PULVERIZE" + nrm + " is an Ogier combat technique. After preparing the attack, you attempt to strike opponents who are fighting you or whom you are fighting." + "\n\n";
    buffer += "You must know Pulverize and wait for its cooldown before using it again. The attempt can fail. It takes no target argument; its combat targets are selected from the fighting around you." + "\n\n";
    buffer += "Example: " + bld + yel + "pulverize" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "KILL" + nrm + ", " + bld + cyn + "PRACTICE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "QUAFF" + nrm + " is a reserved item command. In the current game it has no general potion-drinking effect: specifying an ordinary item does not consume it or apply a potion effect." + "\n\n";
    buffer += "Follow the instructions for the particular item you are trying to use. " + bld + cyn + "USE" + nrm + " works only on items that explicitly support it. Typing " + bld + cyn + "QUAFF" + nrm + " alone asks which item you mean, but that prompt does not mean that every potion can be quaffed." + "\n\n";
    buffer += "Example: " + bld + yel + "quaff vial" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "USE" + nrm + ", " + bld + cyn + "LOOK" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "RAGE" + nrm + " lets a Myrddraal with the Shadow Rage skill draw on dark power to enhance attack speed. Type it again to release the effect." + "\n\n";
    buffer += "You need sufficient shadow strength to begin. Watch your condition while using shadow abilities, and turn Rage off when you no longer want the enhancement. This command takes no target argument." + "\n\n";
    buffer += "Example: " + bld + yel + "rage" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "FADE" + nrm + ", " + bld + cyn + "SCORE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "READ" + nrm + " examines written material or another visible target. Its basic behavior uses the same viewing action as " + bld + cyn + "LOOK" + nrm + "; books, notices, recipes, and quest items may provide their own text or interaction." + "\n\n";
    buffer += "Use an item or feature keyword from your inventory or the room description. Reading a recipe is different from learning it: use " + bld + cyn + "LEARN" + nrm + " when you want to add an eligible recipe to your recipe book." + "\n\n";
    buffer += "Example: " + bld + yel + "read notice" + nrm + "\n";
    buffer += "Example: " + bld + yel + "read recipe" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "LOOK" + nrm + ", " + bld + cyn + "EXAMINE" + nrm + ", " + bld + cyn + "LEARN" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "RELEASE" + nrm + " ends your connection to the One Power. Use it after " + bld + cyn + "EMBRACE" + nrm + " or " + bld + cyn + "SEIZE" + nrm + " when you no longer want to remain connected to the True Source." + "\n\n";
    buffer += "It does not spend practice sessions or remove your learned weaves. To channel again, reconnect to the Source. In certain quests, " + bld + cyn + "RELEASE <CRATE>" + nrm + " is a separate instruction for letting go of a crate you are dragging." + "\n\n";
    buffer += "Example: " + bld + yel + "release" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "SEIZE" + nrm + ", " + bld + cyn + "UNTIE" + nrm + ", " + bld + cyn + "DRAG" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "REPLY" + nrm + " sends a private tell to the player who most recently sent you one. The recipient must still be online and able to receive your tell." + "\n\n";
    buffer += "Check who last contacted you before replying: another incoming tell can change the recipient. Use " + bld + cyn + "TELL <NAME> <MESSAGE>" + nrm + " when you want to choose the recipient explicitly. " + bld + cyn + "TELLS" + nrm + " reviews your received tell history." + "\n\n";
    buffer += "Example: " + bld + yel + "reply I will meet you at the gate." + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "TELL" + nrm + ", " + bld + cyn + "TELLS" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "RESCUE" + nrm + " attempts to draw an attacker away from an ally in your room and onto you. You must know the Rescue skill, and the ally must have an attacker you can take over. The ally must be of your race; you cannot rescue yourself or your opponent." + "\n\n";
    buffer += "A successful rescue makes you the attacker's opponent; you should be ready to withstand the fight. The attempt can fail. Use " + bld + cyn + "ASSIST" + nrm + " when you want to attack alongside your ally rather than pull an opponent off them." + "\n\n";
    buffer += "Example: " + bld + yel + "rescue traveler" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "ASSIST" + nrm + ", " + bld + cyn + "GROUP" + nrm + ", " + bld + cyn + "PRACTICE" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "REST" + nrm + " settles your character into a resting position. Resting allows you to recover between journeys and battles, but you cannot move normally until you stand again." + "\n\n";
    buffer += "You cannot simply lie down in the middle of a fight. Use " + bld + cyn + "STAND" + nrm + " when you are ready to continue, or " + bld + cyn + "SLEEP" + nrm + " if you want to sleep. Sleeping makes you less aware of activity around you than resting." + "\n\n";
    buffer += "Example: " + bld + yel + "rest" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "STAND" + nrm + ", " + bld + cyn + "SLEEP" + nrm + ", " + bld + cyn + "SIT" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
    buffer += bld + cyn + "RESTAT" + nrm + " rerolls your character's statistics. This command is available only while you are exactly level five." + "\n\n";
    buffer += "Using it immediately changes your statistics; it is not a preview. The new result may differ from the one you had before. Review your character afterwards with " + bld + cyn + "SCORE" + nrm + ". Once you advance beyond level five, this command is no longer available." + "\n\n";
    buffer += "Example: " + bld + yel + "restat" + nrm + "\n\n";
    buffer += "SEE ALSO: " + bld + cyn + "SCORE" + nrm + ", " + bld + cyn + "LEVELS" + nrm;
    return strColFormat(buffer, 66);
})();

(function() {
    var buffer = "";
